import{_ as t}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as a,c as o,a as n}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const m=JSON.parse(`{"title":"What's new in v1.8.1","description":"Bug fix: the CLI no longer hangs silently for up to 2 minutes after the pagination bar, especially on slow or mobile networks.","frontmatter":{"title":"What's new in v1.8.1","description":"Bug fix: the CLI no longer hangs silently for up to 2 minutes after the pagination bar, especially on slow or mobile networks.","date":"2026-03-09T00:00:00.000Z"},"headers":[],"relativePath":"blog/release-v1-8-1.md","filePath":"blog/release-v1-8-1.md"}`),s={name:"blog/release-v1-8-1.md"};function r(i,e,l,h,c,d){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="what-s-new-in-github-code-search-v1-8-1" tabindex="-1">What&#39;s new in github-code-search v1.8.1 <a class="header-anchor" href="#what-s-new-in-github-code-search-v1-8-1" aria-label="Permalink to &quot;What&#39;s new in github-code-search v1.8.1&quot;">​</a></h1><blockquote><p>Full release notes: <a href="https://github.com/fulll/github-code-search/releases/tag/v1.8.1" target="_blank" rel="noreferrer">https://github.com/fulll/github-code-search/releases/tag/v1.8.1</a></p></blockquote><h2 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h2><h3 id="fix-silent-hang-after-pagination-bar-on-slow-networks" tabindex="-1">Fix: silent hang after pagination bar on slow networks <a class="header-anchor" href="#fix-silent-hang-after-pagination-bar-on-slow-networks" aria-label="Permalink to &quot;Fix: silent hang after pagination bar on slow networks&quot;">​</a></h3><p>After the <code>Fetching results from GitHub…</code> progress bar completed, the CLI could freeze silently for <strong>up to 2 minutes</strong> before the interactive TUI appeared. No spinner, no message — the terminal looked stuck. The hang was consistently worse on tethering or congested networks and could sometimes be resolved by re-running on a better connection.</p><h4 id="root-cause" tabindex="-1">Root cause <a class="header-anchor" href="#root-cause" aria-label="Permalink to &quot;Root cause&quot;">​</a></h4><p>The GitHub Code Search API returns only fragment-relative character indices — there are no absolute line numbers in the response. To display accurate line numbers in the TUI, <code>github-code-search</code> fetches the raw content of each matched file from <code>raw.githubusercontent.com</code> after pagination completes.</p><p>Two compounding issues caused the hang:</p><ol><li><p><strong>No concurrency limit.</strong> With 200+ unique files in the results, 200+ HTTP requests fired simultaneously via <code>Promise.all</code>. On a saturated network this overwhelmed the connection pool and caused the event loop to stall.</p></li><li><p><strong>No progress feedback.</strong> The user saw nothing between the end of the pagination bar and the TUI — no indication that work was still in progress.</p></li></ol><h4 id="what-changed" tabindex="-1">What changed <a class="header-anchor" href="#what-changed" aria-label="Permalink to &quot;What changed&quot;">​</a></h4><ul><li><p><strong>Concurrency capped at 20</strong> parallel requests (new <code>concurrentMap</code> helper in <code>api-utils.ts</code>). This dramatically reduces the load on the network connection and prevents the stall pattern on mobile networks.</p></li><li><p><strong>Per-request 5 s timeout</strong> via <code>AbortSignal.timeout</code>. If a raw file fetch stalls, it is silently abandoned and line numbers fall back to fragment-relative values — results still appear, just without precise absolute line numbers for that file.</p></li><li><p><strong>New progress bar</strong> shown on stderr during the resolution phase:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span>  Resolving line numbers… ▓▓▓▓▓▓▓░░░░░░░░░░░░░  23/67</span></span></code></pre></div><p>The line is erased cleanly before the TUI launches, leaving a clean terminal.</p></li></ul><p><strong>Before:</strong> silent freeze, up to 2 minutes on tethering.<br><strong>After:</strong> steady progress bar, TUI opens within seconds on any network.</p><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><p>Or download the latest binary directly from the <a href="https://github.com/fulll/github-code-search/releases/tag/v1.8.1" target="_blank" rel="noreferrer">GitHub Releases page</a>.</p>',16)])])}const w=t(s,[["render",r]]);export{m as __pageData,w as default};
